<?php
define('_GNUBOARD_',true);require __DIR__.'/../AvocadoEdition_Light/lib/tomo_maintenance.lib.php';
function verify($ok,$label){if(!$ok)throw new RuntimeException($label);echo "PASS $label\n";}
$root=sys_get_temp_dir().'/tomo-clean-'.bin2hex(random_bytes(6));mkdir($root);mkdir($root.'/session');mkdir($root.'/cache');
foreach(['old','current','recent'] as $name){file_put_contents($root.'/session/sess_'.$name,'fixture');if($name!=='recent')touch($root.'/session/sess_'.$name,time()-30000);}
file_put_contents($root.'/session/index.php','guard');file_put_contents($root.'/outside','keep');symlink($root.'/outside',$root.'/session/sess_link');
$result=tomo_clean_generated_files($root.'/session','session','current');verify($result['deleted']===1&&!file_exists($root.'/session/sess_old'),'only expired sessions removed');verify(file_exists($root.'/session/sess_current')&&file_exists($root.'/session/sess_recent'),'current and recent sessions retained');verify(file_exists($root.'/outside')&&is_link($root.'/session/sess_link')&&file_exists($root.'/session/index.php'),'links and non-session files retained');
file_put_contents($root.'/cache/latest-board-basic-10-40.php','cache');file_put_contents($root.'/cache/other.php','keep');mkdir($root.'/cache/latest-directory.php');symlink($root.'/outside',$root.'/cache/latest-link.php');$result=tomo_clean_generated_files($root.'/cache','cache');verify($result['deleted']===1&&file_exists($root.'/cache/other.php')&&is_dir($root.'/cache/latest-directory.php'),'only generated latest cache files removed');verify(tomo_clean_generated_files($root.'/missing','cache')['error']!=='','missing directory returns a readable result');
file_put_contents($root.'/cache/latest-failed.php','keep');chmod($root.'/cache',0555);$result=tomo_clean_generated_files($root.'/cache','cache');chmod($root.'/cache',0755);verify($result['failed']===1&&$result['deleted']===0&&file_exists($root.'/cache/latest-failed.php'),'failed deletions are not reported as successful');
